

export function codeMirror() {
  (function ($, Drupal, drupalSettings) {

    initMutationObserver();
  

  
    function initMutationObserver() {
  
      const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
          mutation.addedNodes.forEach((addedNode) => {
            if (addedNode.nodeType === 1 && addedNode.classList.contains("noahs_page_builder-modal")) {
              setTimeout(() => {
                customMirror();
              }, 50); 
            }
          });
        }); 
      }); 
  
      observer.observe(document.body, { childList: true, subtree: true });
    }

    /** Función para inicializar CodeMirror en los textareas */
    function customMirror() {
      var textareas = $('.noahs_page_builder_codemirror, .noahs_page_builder_codemirror_js');

      textareas.each(function() {
        var miTextarea = this;
        var modeType = $(miTextarea).hasClass('noahs_page_builder_codemirror_js') ? "javascript" : "css";

        const widget_id = $(miTextarea).closest('form').find('input[name="wid"]').val();

        var miCodeMirror = CodeMirror.fromTextArea(miTextarea, {
          mode: modeType,
          lineNumbers: true,
          theme: "material-darker",
          extraKeys: { "Ctrl-Space": "autocomplete" }
        });

        if (widget_id) {
          miCodeMirror.on("change", function(cm) {
            var currentValue = cm.getValue();
            $(miTextarea).val(currentValue);
            modificarEstilo($(miTextarea), widget_id);
            modificarJson($(miTextarea), widget_id);
          });
        }
      });
    }

  
  $(window).on('load', function() {
    setTimeout(() => {
    customMirror();
  }, 50); 
  });
})(jQuery, Drupal, drupalSettings);
}